INSERT INTO "public"."o_assets" ("id", "projectId", "name", "type", "describe", "prompt", "promptState", "promptErrorReason", "imagePath", "created_at", "updated_at", "imageId", "assetsId", "remark", "startTime", "flowId") VALUES (7, 6, '矿泉水瓶', 'tool', '母亲从帆布包中取出递给女儿的饮用水，瓶身凝着水珠', '3D 动画渲染，电影级打光，活力赛璐珞质感，高细节材质，愉悦治愈氛围，卡通都市风，高细节卡通材质，适度卡通比例，暖色调配色，8K 超高清，电影级构图，柔和光影层次，明快卡通渲染风格，温馨治愈，道具设定图，
anime style, cel-shaded, 3D animation render,
