COMMIT;

-- ----------------------------
-- Table structure for o_tasks
-- ----------------------------
DROP TABLE IF EXISTS "public"."o_tasks";
CREATE TABLE "public"."o_tasks" (
  "id" int4 NOT NULL DEFAULT nextval('o_tasks_id_seq'::regclass),
  "state" varchar(255) COLLATE "pg_catalog"."default" DEFAULT 'pending'::character varying,
  "created_at" timestamptz(6) DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz(6) DEFAULT CURRENT_TIMESTAMP,
  "projectId" int4 NOT NULL,
  "taskClass" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "relatedObjects" text COLLATE "pg_catalog"."default",
  "model" text COLLATE "pg_catalog"."default",
  "describe" text COLLATE "pg_catalog"."default",
  "startTime" timestamptz(6),
  "reason" text COLLATE "pg_catalog"."default"
)
;
ALTER TABLE "public"."o_tasks" OWNER TO "user_toonflow";

