INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (35, '已完成', '2026-04-21 10:30:25.437677+00', '2026-04-21 10:30:25.437677+00', 6, '生成分镜图片', '{"prompt":"@图1 为大巴车厢场景 @图2 为张星辞角色 @图3 为矿泉水瓶道具, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，特写构图，局部细节放大，@图2 的指尖触及冰凉@图3 瓶身，水珠沿掌纹蔓延浸湿指腹，手指微蜷攥紧瓶身，凉意上涌，左侧自然光斜射，指尖水珠反光微亮，掌纹处阴影呈蓝灰色调，清晰轮廓线，明快卡通渲染，高细节材质，写实材质与卡通比例结合，材质纹理清晰，表面质感细腻，柔和光影层次，愉悦治愈氛围，3D动画美学，沉默隐忍情感表达，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference image of @图2, maintain consistent: hand shape, water bottle with condensation. Generate a new scene: close-up of fingers gripping cold water bottle, water droplets spreading along palm lines, blue-grey shadow tones, silent endurance. Keep character appearance identical to reference.","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 10:30:25.435+00', NULL);
INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (26, '已完成', '2026-04-21 07:53:07.359456+00', '2026-04-21 07:53:07.359456+00', 6, '工作流图片生成', '{"references":["http://localhost:10588/oss/smallImage/6/scene/7e9e0e2c-d532-4db2-b545-e2ef9c6df952.jpg","http://localhost:10588/oss/smallImage/6/props/9a64ef43-ec47-44ad-89be-72dcf34b26e7.jpg"],"model":"jimeng:jimeng-5.0","quality":"2K","ratio":"16:9","prompt":"@图1 为大巴车厢场景 @图2 为蛇皮袋道具, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，远景构图，大巴车轮缓缓碾过碎石地面扬起灰尘，@图1 车厢内前景堆叠的@图2随车身轻微晃动，背景空间昏暗压抑，轮胎与地面摩擦扬起细微尘土，自然光从左侧斜射，灰蓝冷调，清晰轮廓线，明快卡通渲染，轮廓线均匀一致，无断线无粗糙边缘，愉悦治愈氛围，3D动画美学，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference image of @图1, maintain consistent: vehicle interior structure, lighting direction, atmosphere. Generate a new scene: wide shot of bus wheel rolling over gravel road, dust rising from tires, foreground cluttered with woven bags, dim interior lighting, cold blue-gray tones. Keep scene appearance identical to reference.","projectId":6}', 'jimeng-5.0', '工作流图片生成', '2026-04-21 07:53:07.356+00', NULL);
