INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (29, '已完成', '2026-04-21 10:29:39.873669+00', '2026-04-21 10:29:39.873669+00', 6, '生成分镜图片', '{"prompt":"@图1 为大巴车厢场景 @图2 为众乘客角色 @图3 为年轻妈妈角色 @图4 为前排婴儿角色 @图5 为蛇皮袋道具 @图6 为翻盖手机道具, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，全景构图，人景比例协调，@图1 车厢内拥挤场景，过道堆满@图5，@图2 肩靠肩，前排@图3 怀抱@图4 低头轻拍哄劝，婴儿脸涨红哭声不断，翻盖@图6 隐约可见，自然光从左侧车窗斜射，面部明暗交错，背景压暗呈蓝灰色调，清晰轮廓线，明快卡通渲染，高细节材质，柔和光影层次，愉悦治愈氛围，3D动画美学，嘈杂压抑情感表达，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference image of @图1 @图2 @图3, maintain consistent: bus interior, passenger appearances, casual clothing. Generate a new scene: crowded bus interior, passengers sitting shoulder to shoulder, young mother holding crying baby in front row. Keep character appearances identical to reference.","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 10:29:39.872+00', NULL);
INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (31, '已完成', '2026-04-21 10:29:39.886797+00', '2026-04-21 10:29:39.886797+00', 6, '生成分镜图片', '{"prompt":"3D 动画渲染，赛璐珞质感，电影级打光，高细节材质，近景构图，人物上半身入镜，背景虚化，清晰轮廓线，明快卡通渲染，轮廓线均匀一致，无断线无粗糙边缘，高细节材质，写实材质与卡通比例结合，材质纹理清晰，表面质感细腻，柔和光影层次，明暗对比清晰，光效柔和自然，愉悦治愈氛围，3D 动画美学，温馨情感表达，现代都市风情，大巴车内，女儿转头直视母亲，眼睛骤然睁大，瞳孔微震，嘴唇微微张开，神情震惊愣住，@图2 面朝左 3/4 侧面，@图3 面朝左 3/4 侧面，@图2 位于画面左侧，@图3 位于画面右侧，窗外霞光逆光打在女儿侧脸轮廓，眼睛受光眼神中倒映车窗光影，表情生动真实，8K 超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。\n@图1 为大巴车厢场景 @图2 为张星辞角色 @图3 为母亲角色, @图2 位于画面左侧，面朝右，转头直视@图3，眼睛睁大，瞳孔微震，嘴唇微张，神情震惊，@图3 位于画面右侧，面朝左，窗外霞光逆光打在侧脸轮廓，@图1 车内氛围，暖橙色光晕。","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 10:29:39.88+00', NULL);
