INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (38, '已完成', '2026-04-21 10:31:24.937451+00', '2026-04-21 10:31:24.937451+00', 6, '生成分镜图片', '{"prompt":"3D 动画渲染，赛璐珞质感，电影级打光，高细节材质，特写构图，唇部区域居中，背景虚化模糊，清晰轮廓线，明快卡通渲染，轮廓线均匀一致，无断线无粗糙边缘，高细节材质，写实材质与卡通比例结合，材质纹理清晰，表面质感细腻，柔和光影层次，明暗对比清晰，光效柔和自然，愉悦治愈氛围，3D 动画美学，温馨情感表达，现代都市风情，大巴车内，母亲嘴唇特写，干裂的唇瓣微微张开，唇边细微气流溢出，唇缝处呈暖橙色高光，干裂纹理阴影清晰，逆光霞光从窗外打在唇部轮廓，唇部皮肤质感细腻，8K 超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。\n@图1 为大巴车厢场景 @图2 为母亲角色, @图2 嘴唇干裂微张，唇缝呈暖橙色高光，干裂纹理阴影可见，逆光霞光打在唇部轮廓，@图1 车内氛围，暖橙色光晕，背景虚化。","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 10:31:24.936+00', NULL);
INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (41, '已完成', '2026-04-21 10:31:24.948578+00', '2026-04-21 10:31:24.948578+00', 6, '生成分镜图片', '{"prompt":"@图1 为大巴车厢场景 @图2 为母亲角色 @图3 为矿泉水瓶道具, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，特写构图，局部细节放大，@图2 的五指缓缓合拢攥紧@图3 半瓶矿泉水，指节泛白收紧，瓶身水珠被掌心捂热沿指缝下淌，左侧冷光侧照，指缝间水珠呈暗色细线，手背明暗对比明显，清晰轮廓线，明快卡通渲染，高细节材质，写实材质与卡通比例结合，材质纹理清晰，表面质感细腻，柔和光影层次，明暗对比清晰，愉悦治愈氛围，3D动画美学，沉默凝重情感表达，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference image of @图2, maintain consistent: hand shape, worn ring area, water bottle with condensation. Generate a new scene: close-up of hand gripping half-full water bottle, fingers tightening, water droplets along finger creases, cold side lighting from left. Keep character appearance identical to reference.","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 10:31:24.942+00', NULL);
