INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (50, '已完成', '2026-04-21 10:34:01.093032+00', '2026-04-21 10:34:01.093032+00', 6, '生成分镜图片', '{"prompt":"@图1 为大巴车厢场景 @图2 为张星辞角色 @图3 为母亲角色 @图4 为浅蓝旧衬衫角色, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，近景构图，上半身入镜，@图2 坐在画面左侧位置，3/4正面面朝右，肩胛微微下沉，头部微低，眼神仍垂落但眉头舒展，肩膀线条松弛（约两秒），母女肩膀间空隙被@图3 手臂填上，左侧自然光微暖照在肩部区域，轮廓边缘泛柔和暖色，面部仍处阴影中，@图4 浅蓝旧衬衫局部可见，清晰轮廓线，明快卡通渲染，高细节材质，柔和光影层次，明暗对比清晰，光效柔和自然，暖色调主导，愉悦治愈氛围，3D动画美学，隐忍温热情感表达，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference image of @图2, maintain consistent: face features, braided hairstyle, relaxed shoulder posture. Generate a new scene: @图2 on left side of frame facing right, shoulders slightly dropping, head微微lowered, gaze still down but tension releasing, gentle warm light on shoulders. Keep character appearance identical to reference.","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 10:34:01.092+00', NULL);
