INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (73, '已完成', '2026-04-21 11:04:17.719355+00', '2026-04-21 11:04:17.719355+00', 6, '生成分镜图片', '{"prompt":"@图1 为大巴车厢场景 @图2 为蛇皮袋道具, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，远景构图，环境全貌，蛇皮袋堆叠在车厢过道，@图2 鼓囊囊堆满前景，大巴车轮缓缓碾过碎石地面扬起细微尘土，背景@图1 车厢晃动，整体灰蓝冷调，自然光从左侧斜射，柔和光影层次，明暗对比清晰，愉悦治愈氛围，3D动画美学，温馨情感表达，现代都市风情，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference image of @图1, maintain consistent: bus interior, window frames, seat materials. Generate a new scene: worn fabric bags piled in bus aisle, wheels rolling over gravel road with dust particles, cold blue-grey atmosphere. Keep environment identical to reference.","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 11:04:17.716+00', NULL);
INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (74, '已完成', '2026-04-21 11:04:17.723261+00', '2026-04-21 11:04:17.723261+00', 6, '生成分镜图片', '{"prompt":"@图1 为大巴车厢场景 @图2 为张星辞角色 @图3 为母亲角色 @图4 为浅蓝旧衬衫角色, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，中景构图，人物膝盖以上入镜，@图1 车厢最后一排，大巴颠簸瞬间，@图3 坐在画面右侧位置，3/4正面面朝左，下意识侧身，右臂缓缓横抬至@图2 肩前轻护（约两秒），@图2 坐在画面左侧位置，3/4正面面朝右，左侧自然光渐转微暖，手臂抬起处窗外光线略打亮@图4 袖口，局部有微暖光点缀，清晰轮廓线，明快卡通渲染，高细节材质，柔和光影层次，明暗对比清晰，光效柔和自然，暖色调主导，愉悦治愈氛围，3D动画美学，温柔笃定情感表达，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference image of @图2 @图3, maintain consistent: face features, braided hairstyle, worn light blue shirt, protective gesture. Generate a new scene: @图3 on right side of frame facing left, arm gently crossing to protect @图2 on left side of frame facing right, warm light slightly illuminating sleeve, gentle determined atmosphere. Keep character appearances identical to reference.","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 11:04:17.721+00', NULL);
INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (75, '已完成', '2026-04-21 11:04:17.731694+00', '2026-04-21 11:04:17.731694+00', 6, '生成分镜图片', '{"prompt":"@图1 为大巴车厢场景 @图2 为众乘客角色 @图3 为年轻妈妈角色 @图4 为前排婴儿角色 @图5 为蛇皮袋道具 @图6 为翻盖手机道具, 3D动画渲染，赛璐珞质感，电影级打光，高细节材质，全景构图，@图1 车厢内过道堆满@图5，@图2 肩靠肩挤满座位，@图3 怀抱@图4 低头轻拍哄劝，婴儿脸涨红哭声不断，@图6 翻盖手机隐约可见，乘客侧身让座翻找行李，左侧车窗自然光斜射，面部明暗交错，背景压暗呈蓝灰色调，清晰轮廓线，明快卡通渲染，轮廓线均匀一致，无断线无粗糙边缘，愉悦治愈氛围，3D动画美学，8K超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。Based on the reference images of @图1 @图2 @图3 @图4, maintain consistent: vehicle interior structure, character positions, clothing details. Generate a new scene: panoramic view of crowded bus interior, aisle filled with woven bags, young mother holding crying baby in front row, elderly passengers shoulder to shoulder, flip phone visible, blue-gray tones, side lighting from left window. Keep characters identical to reference.","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 11:04:17.723+00', NULL);
INSERT INTO "public"."o_tasks" ("id", "state", "created_at", "updated_at", "projectId", "taskClass", "relatedObjects", "model", "describe", "startTime", "reason") VALUES (76, '已完成', '2026-04-21 11:05:15.981074+00', '2026-04-21 11:05:15.981074+00', 6, '生成分镜图片', '{"prompt":"3D 动画渲染，赛璐珞质感，电影级打光，高细节材质，中景构图，缓推镜头从车厢全景推进至最后一排，@图2 靠内侧扎两条细辫神情木然，@图3 靠窗头抵车窗玻璃，碎发粘颊，@图2 位于画面左侧3/4正面朝右，@图3 位于画面右侧3/4正面朝左，清晰轮廓线，明快卡通渲染，轮廓线均匀一致，无断线无粗糙边缘，高细节材质，写实材质与卡通比例结合，材质纹理清晰，表面质感细腻，左侧车窗斜光打在母女侧脸，面部明暗各半，柔和光影层次，明暗对比清晰，光效柔和自然，木然疏离氛围，3D 动画美学，现代都市风情，愉悦治愈氛围，8K 超高清，线条清晰，材质细腻，色彩饱满，画面无杂色无噪点。@图1 为大巴车厢场景 @图2 为张星辞角色 @图3 为母亲角色, @图1 内缓推至最后一排，@图2 靠内侧扎两条细辫神情木然，位于画面左侧3/4正面朝右，@图3 靠窗头抵玻璃，位于画面右侧3/4正面朝左，母女并排静坐。","size":"2K","aspectRatio":"16:9"}', 'jimeng-5.0', '分镜图片生成', '2026-04-21 11:05:15.975+00', NULL);
