-- ----------------------------
-- Table structure for o_vendorConfig
-- ----------------------------
DROP TABLE IF EXISTS "public"."o_vendorConfig";
CREATE TABLE "public"."o_vendorConfig" (
  "id" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "inputValues" text COLLATE "pg_catalog"."default",
  "models" text COLLATE "pg_catalog"."default",
  "enable" int4 DEFAULT 0,
  "created_at" timestamptz(6) DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamptz(6) DEFAULT CURRENT_TIMESTAMP
)
;
ALTER TABLE "public"."o_vendorConfig" OWNER TO "user_toonflow";

