INSERT INTO "public"."o_videoTrack" ("id", "videoId", "trackIndex", "order", "created_at", "scriptId", "projectId", "duration", "prompt") VALUES (24, NULL, NULL, 0, '2026-04-21 10:49:19.644938+00', 33, 6, 5, NULL);
INSERT INTO "public"."o_videoTrack" ("id", "videoId", "trackIndex", "order", "created_at", "scriptId", "projectId", "duration", "prompt") VALUES (14, NULL, NULL, 0, '2026-04-21 07:54:19.548004+00', 33, 6, 4, '3D 动画渲染，赛璐珞质感，电影级光影，温暖色调，高细节材质，清晰轮廓线。大巴车厢内，左侧车窗自然光斜射，形成柔和光影层次。张星辞，3/4 正面朝右，现代简约装扮，深棕发色，暖橙肤色基底。面部写实材质与卡通比例结合，柔和光影。目光从母亲小臂疤痕短暂停留后迅速移开，缓缓垂落至膝盖，手指慢慢收拢轻攥裤腿，传递隐忍克制情绪。面部受光面温暖，阴影面柔和过渡无死黑，眼神闪避后垂落显沉重，清晰轮廓线勾勒发丝与自然光影层次。背景现代大巴内饰，高级灰与天空蓝点缀环境，场景色调贴合离别感伤情绪，整体暖底冷暖对比，治愈系温暖质感，浅景深，缓慢下移运镜，4 秒镜头，高细节材质渲染。');
INSERT INTO "public"."o_videoTrack" ("id", "videoId", "trackIndex", "order", "created_at", "scriptId", "projectId", "duration", "prompt") VALUES (15, NULL, NULL, 0, '2026-04-21 07:54:24.608885+00', 33, 6, 4, '3D 动画渲染，赛璐珞质感，电影级光影，温暖色调，高细节材质，清晰轮廓线。日常温馨场景，暖黄基底搭配高级灰与天空蓝点缀。大巴车厢内，日景，中景镜头缓慢推进。一位中年母亲，肤色暖橙，深棕色头发，身穿浅蓝旧衬衫，领口微皱呈冷灰色调。右手缓缓伸入磨损毛边的帆布包，指尖触及矿泉水瓶后轻轻抽出攥在手中，包带毛边蹭过手心，动作迟缓沉默。自然光从左侧斜射，光线柔和稍暗，整体保持暖底冷调对比。背景为现代大巴座椅，米白与高级灰配色。画面治愈温暖，细节丰富，面部写实材质与卡通比例结合，发丝清晰轮廓线，无写实渲染，无暗调重阴影。时长 4 秒。');
INSERT INTO "public"."o_videoTrack" ("id", "videoId", "trackIndex", "order", "created_at", "scriptId", "projectId", "duration", "prompt") VALUES (5, NULL, NULL, 0, '2026-04-21 07:50:33.679817+00', 33, 6, 19, NULL);
